// Turn n8n's error event into an alert email. The same error from the same
// workflow is sent at most once every 6 hours, so a failure that repeats on every
// hourly monitor run doesn't flood the inbox.
const e = $input.first().json;
const wf = e.workflow || {};
const ex = e.execution || {};
const message = String(ex.error?.message || e.trigger?.error?.message || 'Unknown error');
const step = ex.lastNodeExecuted || e.trigger?.node?.name || 'unknown';
const state = $getWorkflowStaticData('global');
state.sent = state.sent || {};
const now = Date.now();
const key = (wf.id || wf.name) + '|' + message.slice(0, 200);
if (state.sent[key] && now - state.sent[key] < 6 * 3600000) return [];
state.sent[key] = now;
// Forget week-old entries so the stored state stays small.
for (const k of Object.keys(state.sent)) if (now - state.sent[k] > 7 * 86400000) delete state.sent[k];

const esc = (v) => String(v ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const html = '<div style="font-family:-apple-system,Segoe UI,sans-serif;color:#1f2328;max-width:680px">'
  + '<h2 style="margin:0 0 12px">A Domain Guard workflow failed</h2>'
  + '<p><b>Workflow:</b> ' + esc(wf.name || 'unknown') + '<br><b>Failed step:</b> ' + esc(step) + '<br><b>Error:</b> ' + esc(message) + '<br><b>Time:</b> ' + new Date(now).toISOString() + '</p>'
  + (ex.url ? '<p><a href="' + esc(ex.url) + '">Open the failed run in n8n</a></p>' : '')
  + '<p style="color:#57606a">Until this is fixed, the workflow may keep failing. Repeats of this same error are not emailed again for 6 hours.</p>'
  + '</div>';
return [{ json: { subject: 'Domain Guard FAILURE: ' + (wf.name || 'unknown workflow') + ' (' + step + ')', html } }];
